// Shared classroom/calculator view. Scientific results are supplied by Python.
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=(rows,value)=>rows.map(([id,title])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(title)}</option>`).join('');
const table=(heads,rows)=>`<div class="obs-table"><table><thead><tr>${heads.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const pretty=x=>typeof x==='string'?x:JSON.stringify(x,null,2);
const params={phonons:{preset:'silicon',angle:45,polarization:'parallel',mode:'sum',channel:'raman',frequency_cm1:300,width_cm1:20,amplitude:.10,steps:48},tensors:{preset:'cubic_m3m',tensor:'dielectric',orientation_deg:0,field:[1,0,0],strain:[1,0,0,0,0,1],parameters:{},plane:'xy'}};
let catalogPromise,lastResult=null;
const catalog=()=>catalogPromise??=(fetch('data/material-observables.json?v=20261027-quantum1').then(r=>{if(!r.ok)throw Error('材料物性课程暂未载入');return r.json();}).catch(e=>{catalogPromise=null;throw e;}));
export const getObservablesResult=()=>lastResult;
export function formatDecomposition(rows){return (rows||[]).map(r=>(r.multiplicity===1?'':r.multiplicity+' ')+r.irrep).join(' ⊕ ')||'无';}
export function curveSVG(points,xLabel,yLabel){
 const clean=points.filter(p=>Array.isArray(p)&&p.length===2&&p.every(Number.isFinite));if(!clean.length)return '';
 const xs=clean.map(p=>p[0]),ys=clean.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(0,...ys),ymax=Math.max(0,...ys),dx=xmax-xmin||1,dy=ymax-ymin||1;
 const line=clean.map(([x,y])=>`${60+600*(x-xmin)/dx},${250-205*(y-ymin)/dy}`).join(' ');
 return `<svg class="obs-curve" viewBox="0 0 720 305" role="img" aria-label="${esc(xLabel+'与'+yLabel+'曲线')}"><title>${esc(yLabel)}</title><path d="M60 25V250H680" fill="none" stroke="#9daea8"/><polyline points="${line}" fill="none" stroke="#287c66" stroke-width="3"/><text x="60" y="276">${esc(Number(xmin.toPrecision(4)))}</text><text x="620" y="276">${esc(Number(xmax.toPrecision(4)))}</text><text x="310" y="298">${esc(xLabel)}</text><text x="65" y="20">${esc(yLabel)} · max ${esc(Number(ymax.toPrecision(4)))}</text></svg>`;
}
const sourcesHTML=(items=[])=>`<div class="obs-sources">${items.map(s=>{const url=typeof s==='string'?s:s.url;return /^https:\/\//.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noreferrer">${esc(s.title||url)} ↗</a>`:'';}).join('')}</div>`;
export async function renderObservablesView({container,selection={},run,cancelRun,download,onNavigate=()=>{},onLocation=()=>{}}){
 container.innerHTML='<div class="obs-page"><p role="status">正在准备材料物性课堂…</p></div>';
 const root=container.firstElementChild,current=()=>root.parentNode===container&&container.isConnected!==false;
 lastResult=null;
 let data;try{data=await catalog();}catch(e){if(current())root.innerHTML=`<p role="alert">${esc(e.message)}</p>`;return;}if(!current())return;
 let tab=selection.calculationOnly?'lab':(['learn','lab','derive','cases'].includes(selection.tab)?selection.tab:'learn');
 let material=data.cases.find(x=>x.id===selection.material)||data.cases[0];
 let lesson=data.lessons.find(x=>x.id===selection.lesson)||data.lessons[0];
 let exercise=data.exercises.find(x=>x.id===selection.exercise)||data.exercises.find(x=>x.lesson===lesson.id)||data.exercises[0];
 if(tab==='derive'&&selection.exercise)lesson=data.lessons.find(x=>x.id===exercise.lesson)||lesson;
 let tool=selection.experiment==='tensors'?'tensors':'phonons', result=null,payload=null,busy=false,ticket=0,stopAnimation=()=>{};
 let completed={};try{completed=JSON.parse(localStorage.getItem('symmetry-lab.observables.progress.v1')||'{}');if(!completed||typeof completed!=='object'||Array.isArray(completed))completed={};}catch{}
 const forms={phonons:{...params.phonons},tensors:{...params.tensors}};
 function applyCase(){forms.phonons.preset=material.phononPreset;forms.phonons.channel=material.id==='nacl'?'ir':'raman';forms.tensors.parameters=material.id==='gaas'?{a1:1}:{};forms.tensors.strain=[0,0,0,.02,0,0];forms.tensors.preset=material.tensorPreset;forms.tensors.tensor=material.tensorProperty;}
 applyCase();if(selection.preset&&selection.calculationOnly)forms[tool].preset=selection.preset;
 const $=s=>root.querySelector(s);
 function sync(){onNavigate({tab,lesson:lesson.id,material:material.id,experiment:tool,exercise:tab==='derive'?exercise.id:undefined});}
 function invalidate(){result=null;payload=null;lastResult=null;ticket++;stopAnimation();}
 function caseLinks(c){return `<div class="obs-links"><a href="#classroom/observables?material=${esc(c.id)}&lesson=${esc(c.lessonIds[0])}">学习推导 →</a><a href="#compute/phonons?material=${esc(c.id)}">声子与光谱 →</a><a href="#compute/tensors?material=${esc(c.id)}">物性张量 →</a><a href="#classroom/structure-dynamics?material=${esc(c.id)}">相变、衍射与数据导入 →</a><a href="#atlas/materials?material=${esc(c.id)}">晶体结构与操作 →</a></div>`;}
 function draw(){if(!current())return;stopAnimation();onLocation((selection.calculationOnly?'计算中心':'学习中心 / 材料物性')+' / '+(selection.calculationOnly?(tool==='phonons'?'声子与光谱':'物性张量'):lesson.title));
 root.innerHTML=`<div class="obs-header"><span class="obs-eyebrow">SYMMETRY → OBSERVABLES</span><h2>${selection.calculationOnly?(tool==='phonons'?'从位移表示到光谱选择定则':'从对称操作到允许的物性张量'):'让群论走进可观测的材料性质'}</h2><p>以 Si、GaAs、NaCl 为线索，连接结构、表示、响应与实验几何。</p></div>${selection.calculationOnly?'':`<nav class="obs-tabs" aria-label="材料物性课程内容">${[['learn','课程讲解'],['lab','交互实验'],['derive','分步练习'],['cases','材料案例']].map(([id,t])=>`<button type="button" data-obs-tab="${id}" aria-pressed="${tab===id}" class="${tab===id?'active':''}">${t}</button>`).join('')}</nav>`}<div class="obs-case-bar"><label>案例导航（计算模型可另选）<select id="obs-material">${options(data.cases.map(c=>[c.id,c.formula+' · '+c.name]),material.id)}</select></label><p>${esc(material.summary)}</p></div><div id="obs-content"></div>`;
 root.querySelectorAll('[data-obs-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.obsTab;draw();sync();});
 $('#obs-material').onchange=e=>{material=data.cases.find(x=>x.id===e.target.value);invalidate();applyCase();draw();sync();};
 if(tab==='learn')drawLearn();else if(tab==='derive')drawExercise();else if(tab==='cases')drawCases();else drawLab();
 }
 function drawLearn(){const relevant=data.exercises.filter(e=>e.lesson===lesson.id);$('#obs-content').innerHTML=`<label class="obs-chapter">选择主题<select id="obs-lesson">${options(data.lessons.map(x=>[x.id,x.title]),lesson.id)}</select></label><article class="obs-lesson"><h2>${esc(lesson.title)}</h2><p class="obs-lead">${esc(lesson.summary)}</p>${lesson.sections.map(s=>`<section><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p>${s.formula?`<div class="obs-formula">${esc(s.formula)}</div>`:''}</section>`).join('')}${(lesson.examples||[]).map(e=>`<aside class="obs-example"><h3>${esc(e.title)}</h3><ol>${e.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p><strong>${esc(e.result)}</strong></p></aside>`).join('')}<div class="obs-links"><button id="obs-learn-lab" class="primary">打开交互实验 →</button>${relevant.length?'<button id="obs-learn-exercise" class="secondary">分步推导练习 →</button>':''}</div>${caseLinks(material)}${sourcesHTML(data.sources.filter(s=>(lesson.references||[]).includes(s.id)))}</article>`;
 $('#obs-lesson').onchange=e=>{lesson=data.lessons.find(x=>x.id===e.target.value);draw();sync();};$('#obs-learn-lab').onclick=()=>{tool=['neumann','piezoelectricity','magnetoelectricity'].includes(lesson.id)?'tensors':'phonons';tab='lab';if(lesson.id==='neumann')forms.tensors.tensor='dielectric';if(lesson.id==='piezoelectricity')forms.tensors.tensor='piezoelectric';if(lesson.id==='magnetoelectricity'){forms.tensors.preset='custom';forms.tensors.tensor='magnetoelectric';forms.tensors.generators=[{rotation:[[-1,0,0],[0,-1,0],[0,0,-1]],time_reversal:true}];forms.tensors.plane='xz';}forms.tensors.parameters={};invalidate();draw();sync();};if($('#obs-learn-exercise'))$('#obs-learn-exercise').onclick=()=>{exercise=relevant[0];tab='derive';draw();sync();};
 }
 function drawCases(){$('#obs-content').innerHTML=`<div class="obs-case-grid">${data.cases.map(c=>`<article><span class="obs-eyebrow">${esc(c.formula)}</span><h2>${esc(c.name)}</h2><p>${esc(c.phase)}</p><h3>${esc(c.question)}</h3><p>${esc(c.answer)}</p>${caseLinks(c)}<details><summary>模型范围与来源</summary><ul>${c.limitations.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${sourcesHTML(data.sources.filter(s=>c.references.includes(s.id)))}</details></article>`).join('')}</div>`;}
 function drawExercise(){let step=0;$('#obs-content').innerHTML=`<label class="obs-chapter">选择练习<select id="obs-exercise">${options(data.exercises.map(e=>[e.id,(completed[e.id]?'✓ ':'')+e.title]),exercise.id)}</select></label><article class="obs-lesson"><h2>${esc(exercise.title)}</h2><p>${esc(exercise.prompt)}</p><div id="obs-steps"></div><p id="obs-progress" role="status"></p>${caseLinks(material)}</article>`;$('#obs-exercise').onchange=e=>{exercise=data.exercises.find(x=>x.id===e.target.value);lesson=data.lessons.find(x=>x.id===exercise.lesson)||lesson;draw();sync();};
 const next=()=>{const s=exercise.steps[step],idx=step;const el=document.createElement('section');el.className='obs-exercise-step';el.innerHTML=`<h3>第 ${idx+1} / ${exercise.steps.length} 步</h3><p>${esc(s.prompt)}</p><details><summary>查看提示</summary><p>${esc(s.hint)}</p></details><div class="obs-choices">${s.choices.map((c,i)=>`<button type="button" class="secondary" data-answer="${i}">${esc(c)}</button>`).join('')}</div><p role="status" class="obs-feedback"></p>`;$('#obs-steps').appendChild(el);el.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const correct=+b.dataset.answer===s.answer;el.querySelector('.obs-feedback').textContent=correct?'✓ '+s.explanation:'再想一想：'+s.hint;if(!correct)return;el.querySelectorAll('button').forEach(x=>x.disabled=true);step++;if(step<exercise.steps.length)next();else {completed[exercise.id]=true;try{localStorage.setItem('symmetry-lab.observables.progress.v1',JSON.stringify(completed));}catch{}$('#obs-progress').textContent='✓ 全部步骤完成。现在可以改变实验参数，检查推导是否仍然成立。';}});};next();
 }
 function drawLab(){const f=forms[tool];$('#obs-content').innerHTML=`${selection.calculationOnly?'':`<div class="obs-tabs"><button data-tool="phonons" class="${tool==='phonons'?'active':''}">声子与光谱</button><button data-tool="tensors" class="${tool==='tensors'?'active':''}">物性张量</button></div>`}<div class="obs-lab-layout"><form id="obs-form" class="obs-controls"><fieldset id="obs-fields" ${busy?'disabled':''}><legend>实验参数</legend>${tool==='phonons'?phononControls(f):tensorControls(f)}<button class="primary" type="submit">${busy?'Python 计算中…':'计算并更新演示 →'}</button></fieldset><p class="obs-small">计算在浏览器内的 Python 中完成。修改参数后重新计算，结果与导出会一同更新。</p></form><section id="obs-output" aria-live="polite" aria-busy="${busy}"></section></div>${caseLinks(material)}`;
 root.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{if(b.dataset.tool!==tool){tool=b.dataset.tool;invalidate();draw();sync();}});
 $('#obs-form').oninput=e=>{if(tool==='tensors'&&['obs-preset','obs-tensor'].includes(e.target?.id)){forms.tensors.parameters={};$('#obs-parameters').value='{}';}if(e.target?.id==='obs-angle'&&e.target.nextElementSibling)e.target.nextElementSibling.textContent=e.target.value+'°';if(!busy){invalidate();$('#obs-output').innerHTML='<p class="obs-placeholder">参数已改变，请重新计算。</p>';}};
 $('#obs-form').onsubmit=async e=>{e.preventDefault();if(busy)return;try{readForm();}catch(error){$('#obs-output').innerHTML=`<p role="alert">${esc(error.message)}</p>`;return;}busy=true;invalidate();const job=ticket,input=JSON.parse(JSON.stringify(forms[tool])),action=tool;$('#obs-fields').disabled=true;$('#obs-output').innerHTML='<p role="status"><span class="spinner"></span> Python 正在求解；首次运行需要下载计算环境…</p>';$('#obs-output').setAttribute('aria-busy','true');try{const answer=await run(action,input);if(!current()||job!==ticket)return;result=answer;payload=input;lastResult={kind:'material-observables',tool:action,material:material.id,input:payload,result};drawOutput();}catch(error){if(current()&&job===ticket)$('#obs-output').innerHTML=`<p role="alert" class="notice error">${esc(error.message)}</p>`;}finally{busy=false;if(current()){if($('#obs-fields'))$('#obs-fields').disabled=false;if($('#obs-output'))$('#obs-output').setAttribute('aria-busy','false');}}};
 if(result)drawOutput();else $('#obs-output').innerHTML='<div class="obs-placeholder"><span>01 → 02 → 03</span><h3>选择模型，计算约束，检验物理结论。</h3><p>声子工具覆盖三种二原子 fcc 原胞模型的 Γ 点；张量工具支持预设点群与自定义笛卡尔生成元。</p></div>';
 }
 function phononControls(f){return `<label>晶体模型<select id="obs-preset">${options([['silicon','Si · 金刚石 · Oh'],['gaas','GaAs · 闪锌矿 · Td'],['nacl','NaCl · 岩盐 · Oh']],f.preset)}</select></label><label>光谱通道<select id="obs-channel">${options([['raman','一阶非共振 Raman'],['ir','电偶极红外 IR']],f.channel)}</select></label><label>偏振几何<select id="obs-polarization">${options([['parallel','平行偏振'],['crossed','交叉偏振']],f.polarization)}</select></label><label>简并分量<select id="obs-mode">${options([['sum','非相干求和（三个分量）'],['x','x 分量'],['y','y 分量'],['z','z 分量']],f.mode)}</select></label><label>偏振方位角 θ（°）<input id="obs-angle" type="range" min="0" max="360" step="5" value="${f.angle}"><output>${f.angle}°</output></label><label>假设峰位（cm⁻¹）<input id="obs-frequency" type="number" min="10" max="4000" value="${f.frequency_cm1}"></label><label>假设线宽 FWHM（cm⁻¹）<input id="obs-width" type="number" min="0.1" max="500" step="0.1" value="${f.width_cm1}"></label><p class="obs-small">峰位、线宽是可调的示意输入。对称性只决定允许性，不预测频率或绝对强度。</p>`;}
 function tensorControls(f){return `<label>点群 / 磁点群<select id="obs-preset">${options([['cubic_m3m','m−3m · 立方中心对称'],['zincblende_td','−43m · 闪锌矿'],['tetragonal_4mm','4mm · 四方极性'],['magnetic_minus3mprime','−3′m′ · 磁电模型'],['gray_triclinic','−1 1′ · 中心对称灰群'],['custom','自定义生成元']],f.preset)}</select></label><label>平衡态物性<select id="obs-tensor">${options([['dielectric','对称介电张量（rank 2）'],['elasticity','弹性刚度（rank 4）'],['piezoelectric','压电张量（rank 3）'],['magnetoelectric','线性磁电张量（rank 2）']],f.tensor)}</select></label><label>晶体绕实验室 z 轴转角（°）<input id="obs-angle" type="range" min="0" max="360" step="5" value="${f.orientation_deg}"><output>${f.orientation_deg}°</output></label><label>扫描外场 / 单轴应变方向的平面<select id="obs-plane">${options([['xy','xy 平面'],['xz','xz 平面'],['yz','yz 平面']],f.plane)}</select></label><label>外场向量 [x,y,z]<input id="obs-field" value="${esc(JSON.stringify(f.field))}"></label><label>应变 [xx,yy,zz,2yz,2xz,2xy]<input id="obs-strain" value="${esc(JSON.stringify(f.strain))}"></label><label>独立参数（JSON；空对象采用演示值）<textarea id="obs-parameters" rows="2">${esc(JSON.stringify(f.parameters))}</textarea></label><details ${f.preset==='custom'?'open':''}><summary>自定义笛卡尔正交生成元</summary><label>generators JSON<textarea id="obs-generators" rows="7">${esc(JSON.stringify(f.generators||[{rotation:[[-1,0,0],[0,-1,0],[0,0,1]],time_reversal:false}],null,2))}</textarea></label><p class="obs-small">自定义模式才使用此输入。矩阵允许整数、分数或 sqrt(3)/2 等精确实数。time_reversal 指该操作是否同时反演时间。</p></details>`;}
 function readForm(){const f=forms[tool];f.preset=$('#obs-preset').value;if(tool==='phonons'){Object.assign(f,{angle:Number($('#obs-angle').value),channel:$('#obs-channel').value,polarization:$('#obs-polarization').value,mode:$('#obs-mode').value,frequency_cm1:Number($('#obs-frequency').value),width_cm1:Number($('#obs-width').value)});}else{try{Object.assign(f,{tensor:$('#obs-tensor').value,plane:$('#obs-plane').value,orientation_deg:Number($('#obs-angle').value),field:JSON.parse($('#obs-field').value),strain:JSON.parse($('#obs-strain').value),parameters:JSON.parse($('#obs-parameters').value)});if(f.preset==='custom')f.generators=JSON.parse($('#obs-generators').value);else delete f.generators;}catch{throw Error('外场、应变、参数和生成元须为合法 JSON。');}}}
 function drawOutput(){const out=$('#obs-output');if(!out||!result)return;out.innerHTML=(tool==='phonons'?phononOutput(result):tensorOutput(result))+`<div class="obs-links"><button id="obs-download" class="secondary">↓ 输入与结果 JSON</button><a href="docs/material-observables.md" target="_blank">方法与范围 ↗</a></div><details><summary>完整计算数据与校验</summary><pre>${esc(JSON.stringify(result,null,2))}</pre></details>${sourcesHTML(result.sources||[])}`;$('#obs-download').onclick=()=>download(JSON.stringify(lastResult,null,2),`symmetry-${tool}-${material.id}.json`);if(tool==='phonons')startViewer(result);}
 function phononOutput(r){
 const p=r.polarization||{},s=r.spectrum||{};
 return `<h2>${esc(r.material?.name||r.material?.formula||r.material||'Γ 点振动')}</h2><div class="obs-result-stats"><div><small>机械表示 · 3N</small><strong>${esc(formatDecomposition(r.decomposition?.mechanical))}</strong></div><div><small>声学平移</small><strong>${esc(formatDecomposition(r.decomposition?.acoustic))}</strong></div><div><small>光学振动</small><strong>${esc(formatDecomposition(r.decomposition?.optical))}</strong></div></div>${table(['光学不可约表示','维数','红外允许','Raman 允许'],(r.decomposition?.optical||[]).map(x=>[x.irrep,x.dimension*x.multiplicity,x.ir?'是':'否',x.raman?'是':'否']))}<div id="obs-vibration"></div><h3>偏振与示意谱</h3><p>当前相对偏振因子：<strong>${esc(Number(Number(p.intensity).toPrecision(5)))}</strong>。线偏振位于晶体 xy 平面；Raman 张量元与 IR 有效偶极导数取 1。${p.channel==='ir'?'红外吸收只使用入射电场，不使用出射分析器的平行或交叉设置。':'不同最终简并模式按强度非相干相加。'}</p><p>表示允许耦合，并不保证每种偏振几何都有信号。例如 xy 平面的电场不能激发 z 方向的电偶极。</p>${curveSVG((p.pattern||[]).map(x=>[x.angle??x.theta,x.intensity]),'偏振方位角 θ / °','相对偏振因子')}<p class="obs-model-note"><strong>用户假设峰位 ${esc(s.assumedFrequencyCm1)} cm⁻¹，FWHM ${esc(s.fwhmCm1)} cm⁻¹。</strong>这是可调的 Lorentzian 单线示意，不是材料实测或计算的声子频率；曲线纵轴不表示绝对强度。</p>${curveSVG((s.points||[]).map(x=>[x.wavenumber,x.intensity]),'波数 / cm⁻¹','假设 Lorentzian 谱')}<p class="obs-model-note">原子箭头表示相对位移的对称适配基；动画不代表由力常数求得的质量加权本征模。当前展示 ${esc(r.animatedMode||'z')} 分量${r.selectedMode==='sum'?'；简并分量求和仅用于光谱强度':''}。</p><details><summary>机械特征标与逐步分解</summary>${table(['共轭类','类大小','χ机械','χ声学','χ光学'],(r.classes||[]).map(x=>[x.label,x.size,x.mechanical,x.acoustic,x.optical]))}<ol>${(r.derivation||[]).map(d=>`<li><h4>${esc(d.title)}</h4><div class="obs-formula">${esc(d.formula)}</div><p>${esc(d.explanation)}</p></li>`).join('')}</ol></details><details><summary>模型范围与物理假设</summary><ul>${(r.scope||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ul></details>`;
 }
 function tensorOutput(r){const rows=r.form||[],response=r.response||{};return `<h2>${esc(r.group?.label||'张量约束')}</h2><p>${esc(r.tensor?.equation)}</p><div class="obs-result-stats"><div><small>独立参数</small><strong>${esc(r.independent_count)}</strong></div><div><small>参数符号</small><strong>${esc((r.symbols||[]).join(', ')||'全部为零')}</strong></div></div><h3>晶体坐标中的精确允许形式</h3>${table(['指标',...(r.tensor?.column_labels||[])],rows.map((row,i)=>[r.tensor?.row_labels?.[i]||i+1,...row]))}<p class="obs-model-note">零表示对称性禁止；自由参数表示允许，不保证真实材料取非零值。表中 C / e 分量不缩放；数值收缩的输入为工程应变 (εxx, εyy, εzz, 2εyz, 2εxz, 2εxy)。</p><h3>给定参数后的响应</h3><p>晶体绕实验室 z 轴转过 ${esc(response.orientation_deg)}°；演示参数：${esc(Object.entries(r.parameters||{}).map(([k,v])=>k+' = '+v).join('，')||'无自由参数')}。</p>${table(['输入 '+(response.input_label||'').split(' (')[0],'输出 '+(response.output_label||''),'响应模长'],[[(response.input||[]).map(x=>Number(x.toPrecision(5))).join(', '),(response.output||[]).map(x=>Number(x.toPrecision(5))).join(', '),Number((response.magnitude||0).toPrecision(5))]])}<h3>方向依赖</h3><p>固定上面的晶体转角，在 ${esc(r.curve_plane)} 平面内扫描${esc(r.curve_input)}。该图横轴是外场 / 应变方向，不是晶体转角。</p>${curveSVG((r.azimuth_curve||[]).map(x=>[x.angle_deg,x.magnitude]),'外场 / 应变方向角 / °','响应模长')}<details><summary>旋转后的数值张量</summary>${table(r.tensor?.column_labels||[],response.rotated_form||[])}</details><details><summary>变换律、约束推导与模型假设</summary><div class="obs-formula">${esc(r.transformation_law)}</div><ol>${(r.derivation||[]).map(s=>`<li><strong>${esc(s.title)}</strong><p>${esc(s.detail)}</p></li>`).join('')}</ol><ul>${(r.assumptions||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ul></details>`;}
 function startViewer(r){const dest=$('#obs-vibration'),frames=r.frames||[];if(!dest||!frames.length)return;let frame=0,yaw=-30,playing=false,handle;dest.innerHTML=`<h3>三维对称适配位移</h3><svg id="obs-motion-svg" viewBox="0 0 640 360" role="img" aria-label="原胞中原子的周期位移"><title>三维声子位移示意</title></svg><div class="obs-motion-controls"><button id="obs-play" class="secondary" type="button">播放位移</button><label>振动相位<input id="obs-frame" type="range" min="0" max="${frames.length-1}" value="0"></label><label>观察方位<input id="obs-yaw" type="range" min="-180" max="180" value="-30"></label></div>`;
 const paint=()=>{if(!current()||!$('#obs-motion-svg'))return;const rad=yaw*Math.PI/180,raw=p=>{const [x,y,z]=p;return [Math.cos(rad)*x-Math.sin(rad)*y,.4*(Math.sin(rad)*x+Math.cos(rad)*y)-z];},verts=r.cellVertices||[],edges=r.cellEdges||[],projected=verts.map(raw),xs=projected.map(p=>p[0]),ys=projected.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),scale=Math.min(540/(xmax-xmin+.4),260/(ymax-ymin+.4)),project=p=>{const [x,y]=raw(p);return [320+(x-(xmin+xmax)/2)*scale,180+(y-(ymin+ymax)/2)*scale];};$('#obs-motion-svg').innerHTML='<title>原胞相对位移；观察方向可调</title><defs><marker id="obs-displacement-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#b7833f"/></marker></defs>'+edges.map(([a,b])=>{const p=project(verts[a]),q=project(verts[b]);return `<line x1="${p[0]}" y1="${p[1]}" x2="${q[0]}" y2="${q[1]}" stroke="#b3c7c0"/>`;}).join('')+(frames[frame].sites||[]).map((s,i)=>{const p=project(s.cartesian),base=project(r.sites[i].cartesian),moving=Math.hypot(p[0]-base[0],p[1]-base[1])>1e-6;return `<circle cx="${base[0]}" cy="${base[1]}" r="16" fill="none" stroke="#afc0ba" stroke-dasharray="4 3"/><circle cx="${p[0]}" cy="${p[1]}" r="12" fill="${i?'#c99753':'#338a76'}"/>${moving?`<line x1="${base[0]}" y1="${base[1]}" x2="${p[0]}" y2="${p[1]}" stroke="#b7833f" stroke-width="3" marker-end="url(#obs-displacement-arrow)"/>`:''}<text x="${p[0]+17}" y="${p[1]-10}">${esc(s.species||s.id)}</text>`;}).join('');$('#obs-frame').value=String(frame);};
 stopAnimation=()=>{playing=false;clearTimeout(handle);};const tick=()=>{if(!playing||!current()||!$('#obs-play')){stopAnimation();return;}frame=(frame+1)%frames.length;paint();handle=setTimeout(tick,65);};$('#obs-play').onclick=()=>{playing=!playing;$('#obs-play').textContent=playing?'暂停位移':'播放位移';if(playing)tick();else clearTimeout(handle);};$('#obs-frame').oninput=e=>{stopAnimation();$('#obs-play').textContent='播放位移';frame=+e.target.value;paint();};$('#obs-yaw').oninput=e=>{yaw=+e.target.value;paint();};paint();
 }
 draw();
}
